import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import time

app = Flask(__name__)
DATABASE = '/data/inventory.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        category TEXT NOT NULL,
        price REAL,
        secret_cost REAL,
        supplier_notes TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        key_hash TEXT PRIMARY KEY,
        owner TEXT,
        tier TEXT DEFAULT 'basic'
    )''')
    db.commit()
    db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key', '')
        key_hash = hashlib.sha256(key.encode()).hexdigest()
        db = get_db()
        row = db.execute('SELECT * FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
        if not row:
            return jsonify({'error': 'unauthorized'}), 401
        g.api_tier = row['tier']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/products/search', methods=['GET'])
@require_api_key
def search_products():
    """Search products with filtering and custom field selection."""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')

    # Field selection - users can choose which columns to retrieve
    allowed_fields = ['id', 'name', 'category', 'price']
    if g.api_tier == 'premium':
        allowed_fields.append('supplier_notes')

    fields_param = request.args.get('fields', 'id,name,category,price')
    requested_fields = [f.strip() for f in fields_param.split(',')]

    # Validate each requested field against allowlist
    safe_fields = [f for f in requested_fields if f in allowed_fields]
    if not safe_fields:
        safe_fields = ['id', 'name']

    fields_clause = ', '.join(safe_fields)

    # Build WHERE clause with parameterized category
    # The LIKE pattern allows flexible matching
    like_pattern = request.args.get('pattern', '%')

    query = f"SELECT {fields_clause} FROM products WHERE category = ? AND name LIKE '{like_pattern}' AND price BETWEEN ? AND ?"

    try:
        min_p = float(min_price)
        max_p = float(max_price)
    except ValueError:
        return jsonify({'error': 'invalid price range'}), 400

    try:
        rows = get_db().execute(query, (category, min_p, max_p)).fetchall()
        results = [dict(row) for row in rows]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        app.logger.error(f"DB error: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
@require_api_key
def get_product(product_id):
    db = get_db()
    row = db.execute('SELECT id, name, category, price FROM products WHERE id = ?', (product_id,)).fetchone()
    if row:
        return jsonify(dict(row))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    init_db()
    debug_mode = os.environ.get('FLASK_DEBUG', '0') == '1'
    app.run(host='0.0.0.0', port=8080, debug=debug_mode)
